import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"EmakiKits","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/kits/index.md","filePath":"en/modules/kits/index.md","lastUpdated":0}`),a={name:`en/modules/kits/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="emakikits" tabindex="-1">EmakiKits <a class="header-anchor" href="#emakikits" aria-label="Permalink to “EmakiKits”">​</a></h1><p>EmakiKits is a configuration-driven kit plugin. Join, invite, daily, weekly, monthly, CDK, choice, and generic kits are all defined in YAML, and kit types differ only in configuration</p><ul><li>Kit definitions live under <code>plugins/EmakiKits/kits/</code>: <strong>one kit per YAML file</strong>, and the kit id comes from the <code>id</code> field inside the file, not the file name</li><li>Reward items reference CoreLib item-source shorthands (<code>minecraft-bread</code>, <code>emakiitem-flame_blade</code>, and so on) instead of hand-building materials and lore inside the kit</li><li>There are four reward types: <code>item</code>, <code>money</code>, <code>nested_kit</code> (reference another kit), and <code>action</code> (a CoreLib action pipeline line)</li><li>Each option of a choice kit is a &quot;mini kit&quot; (several rewards); <code>max_select: 1</code> means the player picks exactly one. Every kit inlines its own GUI layout in the <code>choice.gui</code> section</li><li>Supports fixed rewards, weighted random rewards, paid purchases, cumulative open milestones, time windows (always / range / cron), nested child kits, and cycle detection</li><li>Claiming, redeeming, and buying all go through idempotency keys and audit records that survive a restart</li></ul><h2 id="basics" tabindex="-1">Basics <a class="header-anchor" href="#basics" aria-label="Permalink to “Basics”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>1.0.1</code></td></tr><tr><td>Build artifact</td><td><code>EmakiKits-1.0.1.jar</code></td></tr><tr><td>API coordinate</td><td><code>emaki.jiuwu.craft:emaki-kits-api:1.0.1</code> (compile-time only, never put it into <code>plugins/</code>)</td></tr><tr><td>Main command</td><td><code>/emakikits</code> (aliases <code>/emakikit</code>, <code>/ekits</code>)</td></tr><tr><td>Required dependency</td><td>EmakiCoreLib (<code>required: true</code>, <code>join-classpath: true</code>)</td></tr><tr><td>Permission nodes</td><td><code>emakikits.use</code>, <code>emakikits.claim</code>, <code>emakikits.open</code>, <code>emakikits.buy</code>, <code>emakikits.redeem</code>, <code>emakikits.invite</code>, <code>emakikits.admin</code></td></tr><tr><td>Supported platforms</td><td>Paper 26.1+, Folia supported (<code>folia-supported: true</code>)</td></tr></tbody></table><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to “Pages”">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands</a></td><td>Player commands, choice, purchases, CDK, invites, admin commands, and the permission table</td></tr><tr><td><a href="./configuration.html">Configuration</a></td><td><code>config.yml</code> keys, <code>kits/*.yml</code> fields, the four reward types, inlined choice GUI, time windows</td></tr><tr><td><a href="./api.html">API</a></td><td>The <code>emaki-kits-api</code> facade, view models, and the claim event</td></tr></tbody></table><h2 id="kit-types" tabindex="-1">Kit types <a class="header-anchor" href="#kit-types" aria-label="Permalink to “Kit types”">​</a></h2><table tabindex="0"><thead><tr><th>type</th><th>Trigger</th></tr></thead><tbody><tr><td><code>join</code></td><td>A new player&#39;s first join; an existing player&#39;s invite code (UUID or name) must be entered within the play-time window</td></tr><tr><td><code>invite</code></td><td>Granted after an invite relationship is bound, according to <code>reward_target</code></td></tr><tr><td><code>daily</code> / <code>weekly</code> / <code>monthly</code></td><td>One claim per period key derived from <code>cycle.timezone</code></td></tr><tr><td><code>cdk</code></td><td>Redeemed with <code>/emakikits redeem</code>; global-once or per-player-once</td></tr><tr><td><code>choice</code></td><td>Opens the inlined GUI to pick one mini kit; <code>max_select</code> controls how many options can be chosen</td></tr><tr><td><code>generic</code></td><td>Manually claimed, optionally combined with purchases, open milestones, and time windows</td></tr></tbody></table><h2 id="configuration-layout" tabindex="-1">Configuration layout <a class="header-anchor" href="#configuration-layout" aria-label="Permalink to “Configuration layout”">​</a></h2><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiKits/</span></span>
<span class="line"><span>├── config.yml                  # Main config (version, language, storage, economy, invite, CDK, nesting, join window)</span></span>
<span class="line"><span>├── kits/</span></span>
<span class="line"><span>│   ├── join_welcome.yml        # One kit per file; id comes from the id field inside</span></span>
<span class="line"><span>│   ├── invite_reward.yml</span></span>
<span class="line"><span>│   ├── daily_login.yml</span></span>
<span class="line"><span>│   ├── weekly_supply.yml</span></span>
<span class="line"><span>│   ├── monthly_crate.yml</span></span>
<span class="line"><span>│   ├── cdk_global.yml</span></span>
<span class="line"><span>│   ├── cdk_per_player.yml</span></span>
<span class="line"><span>│   ├── choice_starter.yml      # Includes an inlined choice.gui layout</span></span>
<span class="line"><span>│   ├── generic_crate.yml</span></span>
<span class="line"><span>│   └── nested_child.yml        # Referenced by other kits</span></span>
<span class="line"><span>├── gui/                        # Optional external GUI templates (choice.gui_template fallback)</span></span>
<span class="line"><span>├── data/                       # Runtime save (audit, idempotency keys, counters)</span></span>
<span class="line"><span>└── lang/</span></span>
<span class="line"><span>    ├── zh_CN.yml</span></span>
<span class="line"><span>    └── en_US.yml</span></span></code></pre></div><p>With <code>release_default_data: true</code> the ten bundled example kits are released on first start; existing files are never overwritten</p><h2 id="dependencies-and-integrations" tabindex="-1">Dependencies and integrations <a class="header-anchor" href="#dependencies-and-integrations" aria-label="Permalink to “Dependencies and integrations”">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Relationship</th></tr></thead><tbody><tr><td>EmakiCoreLib</td><td>Required: item sources, <code>createConfiguredItem</code>, the action pipeline, GUI service, template loader, economy bridge, cron, and message service</td></tr><tr><td>EmakiItem</td><td>Optional: grant its custom items via the <code>emakiitem-&lt;itemId&gt;</code> shorthand</td></tr><tr><td>Vault / ExcellentEconomy</td><td>Optional: <code>money</code> rewards and <code>purchase</code> debits go through the CoreLib economy bridge; a paid purchase is rejected when no bridge is installed</td></tr></tbody></table><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h2><ol><li>Install EmakiCoreLib and EmakiKits, start once, and confirm the example kits were released under <code>plugins/EmakiKits/kits/</code></li><li>Copy a <code>kits/*.yml</code>, change <code>id</code>, <code>type</code>, and <code>rewards</code>, then run <code>/emakikits reload</code></li><li>Run <code>/emakikits list</code> to confirm the kit loaded, and <code>/emakikits claim &lt;kitId&gt;</code> to verify it</li><li>For a choice kit use <code>/emakikits choose &lt;kitId&gt;</code> to open the inlined GUI; appending option ids skips the GUI</li></ol>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};